CREATE FUNCTION public.release_bundle_catalog() RETURNS TABLE(register text,label text,evidence_label text,verification_check text,owner_action text) LANGUAGE sql IMMUTABLE SET search_path=public AS $$ VALUES ('release_readiness','Release readiness','Release readiness metadata snapshot','matrix-live','publish_owner'),('release_evidence','Release evidence','Release evidence metadata snapshot','audit-append-only','protection_evidence'),('publish_gate','Publish gate human acknowledgements','Publish gate human acknowledgements metadata snapshot','content-review','claims_review'),('release_runbook','Release runbook and rollback drills','Release runbook and rollback drills metadata snapshot','rollback-drill','publish_owner'),('backup_evidence','Backup evidence','Backup evidence metadata snapshot','backup-evidence','backup_evidence'),('protection_evidence','Protection evidence','Protection evidence metadata snapshot','protection-evidence','protection_evidence'),('content_review','Content and claims review','Content and claims review metadata snapshot','content-review','claims_review'),('access_matrix','Access matrix','Access matrix metadata snapshot','matrix-live','superadmin_account'),('verification_campaign','Verification campaign results','Verification campaign results metadata snapshot','matrix-live','preview_access'),('campaign_history','Campaign history','Campaign history metadata snapshot','audit-append-only','preview_access'),('production_readiness','Production test prerequisites','Production test prerequisites metadata snapshot','matrix-live','superadmin_account'),('owner_action_queue','Owner action queue','Owner action queue metadata snapshot','matrix-live','publish_owner'),('golive_decision_pack','Final go-live decision sign-offs','Final go-live decision sign-offs metadata snapshot','matrix-live','publish_owner'),('test_session_workspace','Test session workspace','Test session workspace metadata snapshot','matrix-live','preview_access'),('human_review_console','Human review sign-off rounds','Human review sign-off rounds metadata snapshot','matrix-live','second_reviewer'),('content_approval','Canonical content approval','Canonical content approval metadata snapshot','content-review','claims_review'),('launch_control','Launch-day control center','Launch-day control center metadata snapshot','rollback-drill','publish_owner'),('integration_safety','Integration and provider safety','Integration and provider safety metadata snapshot','no-external','protection_evidence'),('incident_console','Incident and escalation console','Incident and escalation console metadata snapshot','rollback-drill','publish_owner'),('evidence_inspector','Cross-register evidence inspector','Cross-register evidence inspector metadata snapshot','protection-evidence','protection_evidence') $$;
REVOKE ALL ON FUNCTION public.release_bundle_catalog() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.release_bundle_catalog() TO authenticated;
CREATE TABLE public.release_artifact_snapshot(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),register text NOT NULL CHECK(register IN ('release_readiness','release_evidence','publish_gate','release_runbook','backup_evidence','protection_evidence','content_review','access_matrix','verification_campaign','campaign_history','production_readiness','owner_action_queue','golive_decision_pack','test_session_workspace','human_review_console','content_approval','launch_control','integration_safety','incident_console','evidence_inspector')),version int NOT NULL CHECK(version>0),source_fingerprint text NOT NULL CHECK(source_fingerprint ~ '^[a-f0-9]{32}$'),source_version int NOT NULL CHECK(source_version>=0),source_count int NOT NULL CHECK(source_count>=0),observed_status text NOT NULL CHECK(observed_status IN ('passed','pending','blocked','unverified')),blocker_reason text NOT NULL CHECK(blocker_reason IN ('Missing artifact','Source evidence blocked','Source readiness unverified')),recorder uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),correlation_id uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),UNIQUE(register,version));
GRANT SELECT ON public.release_artifact_snapshot TO authenticated; GRANT ALL ON public.release_artifact_snapshot TO service_role;
ALTER TABLE public.release_artifact_snapshot ENABLE ROW LEVEL SECURITY;
CREATE POLICY release_artifact_snapshot_read ON public.release_artifact_snapshot FOR SELECT TO authenticated USING(public.release_scope(auth.uid()) AND auth.jwt()->>'aal'='aal2');
CREATE TABLE public.release_artifact_review(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),snapshot_id uuid NOT NULL REFERENCES public.release_artifact_snapshot(id),outcome text NOT NULL CHECK(outcome IN ('confirmed','concern')),reviewer uuid NOT NULL,reviewer_role text NOT NULL CHECK(reviewer_role IN ('SUPER_ADMIN','OPERATIONS_ADMIN')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),correlation_id uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),UNIQUE(snapshot_id,reviewer));
GRANT SELECT ON public.release_artifact_review TO authenticated; GRANT ALL ON public.release_artifact_review TO service_role;
ALTER TABLE public.release_artifact_review ENABLE ROW LEVEL SECURITY;
CREATE POLICY release_artifact_review_read ON public.release_artifact_review FOR SELECT TO authenticated USING(public.release_scope(auth.uid()) AND auth.jwt()->>'aal'='aal2');
REVOKE ALL ON public.release_artifact_snapshot,public.release_artifact_review FROM PUBLIC,anon;
REVOKE INSERT,UPDATE,DELETE,TRUNCATE ON public.release_artifact_snapshot,public.release_artifact_review FROM authenticated;
CREATE TRIGGER release_artifact_snapshot_immutable BEFORE UPDATE OR DELETE ON public.release_artifact_snapshot FOR EACH ROW EXECUTE FUNCTION public.care_immutable();
CREATE TRIGGER release_artifact_review_immutable BEFORE UPDATE OR DELETE ON public.release_artifact_review FOR EACH ROW EXECUTE FUNCTION public.care_immutable();
CREATE FUNCTION public.release_bundle_source(_register text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE src jsonb; rev jsonb:='[]'; n int; v int; fp text; blocked boolean; source_table text; review_table text;
BEGIN
 SELECT CASE _register WHEN 'release_readiness' THEN 'release_signoffs' WHEN 'release_evidence' THEN 'release_evidence' WHEN 'publish_gate' THEN 'release_review_acks' WHEN 'release_runbook' THEN 'release_drill_runs' WHEN 'backup_evidence' THEN 'backup_evidence' WHEN 'protection_evidence' THEN 'protection_evidence' WHEN 'content_review' THEN 'content_review' WHEN 'access_matrix' THEN 'access_audit' WHEN 'verification_campaign' THEN 'campaign_results' WHEN 'campaign_history' THEN 'campaign_runs' WHEN 'production_readiness' THEN 'test_prerequisites' WHEN 'owner_action_queue' THEN 'owner_action_items' WHEN 'golive_decision_pack' THEN 'decision_signoffs' WHEN 'test_session_workspace' THEN 'test_sessions' WHEN 'human_review_console' THEN 'review_rounds' WHEN 'content_approval' THEN 'content_approval' WHEN 'launch_control' THEN 'launch_control_item' WHEN 'integration_safety' THEN 'integration_safety_item' WHEN 'incident_console' THEN 'incident_console_item' WHEN 'evidence_inspector' THEN 'evidence_inspector_item' END INTO source_table;
 IF source_table IS NULL THEN RAISE EXCEPTION 'INVALID_ARGUMENTS'; END IF;
 SELECT CASE _register WHEN 'release_readiness' THEN 'release_approvals' WHEN 'backup_evidence' THEN 'backup_evidence_confirmations' WHEN 'protection_evidence' THEN 'protection_evidence_confirmations' WHEN 'content_review' THEN 'content_review_acks' WHEN 'access_matrix' THEN 'access_audit_confirmations' WHEN 'verification_campaign' THEN 'campaign_result_confirmations' WHEN 'production_readiness' THEN 'test_prerequisite_reviews' WHEN 'owner_action_queue' THEN 'owner_action_reviews' WHEN 'test_session_workspace' THEN 'test_session_reviews' WHEN 'human_review_console' THEN 'review_decisions' WHEN 'content_approval' THEN 'content_approval_reviews' WHEN 'launch_control' THEN 'launch_control_review' WHEN 'integration_safety' THEN 'integration_safety_review' WHEN 'incident_console' THEN 'incident_console_review' WHEN 'evidence_inspector' THEN 'evidence_inspector_review' END INTO review_table;
 -- Fixed allowlisted tables and structural metadata only; no free-form labels or business data.
 EXECUTE format('SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''v'',coalesce(to_jsonb(t)->>''version'',to_jsonb(t)->>''round'',to_jsonb(t)->>''run_no'',''1''),''lineage'',coalesce(to_jsonb(t)->>''lineage'',to_jsonb(t)->>''item_key'',to_jsonb(t)->>''suite_key'',to_jsonb(t)->>''key'',to_jsonb(t)->>''check_id'',''all''),''status'',coalesce(to_jsonb(t)->>''status'',to_jsonb(t)->>''observed_status'',to_jsonb(t)->>''outcome'',''unverified''),''at'',created_at) ORDER BY id),''[]'') FROM public.%I t',source_table) INTO src;
 IF review_table IS NOT NULL THEN EXECUTE format('SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''status'',coalesce(to_jsonb(t)->>''outcome'',to_jsonb(t)->>''decision'',''unverified''),''at'',created_at) ORDER BY id),''[]'') FROM public.%I t',review_table) INTO rev; END IF;
 fp:=md5(src::text||rev::text);
 SELECT count(*),coalesce(max((x->>'v')::int),0),coalesce(bool_or(x->>'status' IN ('blocked','failed','concern','rejected','approved','rollback_recommended','open')),false) INTO n,v,blocked FROM (SELECT DISTINCT ON (x->>'lineage') x FROM jsonb_array_elements(src) x ORDER BY x->>'lineage',(x->>'v')::int DESC,x->>'at' DESC) latest;
 blocked:=blocked OR EXISTS(SELECT 1 FROM jsonb_array_elements(rev) x WHERE x->>'status' IN ('concern','rejected'));
 RETURN jsonb_build_object('register',_register,'fingerprint',fp,'source_count',n,'source_version',v,'status',CASE WHEN blocked THEN 'blocked' ELSE 'unverified' END,'reason',CASE WHEN n=0 THEN 'Missing artifact' WHEN blocked THEN 'Source evidence blocked' ELSE 'Source readiness unverified' END);
END $$;
REVOKE ALL ON FUNCTION public.release_bundle_source(text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.release_bundle_capture(_register text,_version int) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid(); v int; s jsonb; row release_artifact_snapshot;
BEGIN
 IF u IS NULL OR NOT release_scope(u) THEN RAISE EXCEPTION 'RELEASE_SCOPE_REQUIRED'; END IF; PERFORM care_require_strong();
 IF NOT EXISTS(SELECT 1 FROM release_bundle_catalog() c WHERE c.register=_register) OR _version IS NULL OR _version<0 THEN RAISE EXCEPTION 'INVALID_ARGUMENTS'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('release_bundle:'||_register));
 SELECT coalesce(max(version),0) INTO v FROM release_artifact_snapshot WHERE register=_register;
 IF v<>_version THEN RAISE EXCEPTION 'STALE_VERSION'; END IF;
 s:=release_bundle_source(_register);
 INSERT INTO release_artifact_snapshot(register,version,source_fingerprint,source_version,source_count,observed_status,blocker_reason,recorder) VALUES(_register,v+1,s->>'fingerprint',(s->>'source_version')::int,(s->>'source_count')::int,s->>'status',s->>'reason',u) RETURNING * INTO row;
 RETURN jsonb_build_object('id',row.id,'version',row.version,'correlation_id',row.correlation_id);
END $$;
CREATE FUNCTION public.release_bundle_confirm(_id uuid,_outcome text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid(); e release_artifact_snapshot; role text; row release_artifact_review;
BEGIN
 IF u IS NULL OR NOT release_scope(u) THEN RAISE EXCEPTION 'RELEASE_SCOPE_REQUIRED'; END IF; PERFORM care_require_strong();
 IF _outcome IS NULL OR _outcome NOT IN ('confirmed','concern') THEN RAISE EXCEPTION 'INVALID_ARGUMENTS'; END IF;
 SELECT * INTO e FROM release_artifact_snapshot WHERE id=_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_ARGUMENTS'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('release_bundle:'||e.register));
 IF e.recorder=u THEN RAISE EXCEPTION 'SECOND_REVIEWER_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM release_artifact_snapshot x WHERE x.register=e.register AND x.version>e.version) OR e.source_fingerprint<>(release_bundle_source(e.register)->>'fingerprint') THEN RAISE EXCEPTION 'STALE_VERSION'; END IF;
 SELECT x.role::text INTO role FROM user_roles x WHERE x.user_id=u AND x.partner_id IS NULL AND x.role IN ('SUPER_ADMIN','OPERATIONS_ADMIN') ORDER BY x.role LIMIT 1;
 INSERT INTO release_artifact_review(snapshot_id,outcome,reviewer,reviewer_role) VALUES(e.id,_outcome,u,role) RETURNING * INTO row;
 RETURN jsonb_build_object('id',row.id,'correlation_id',row.correlation_id);
END $$;
CREATE FUNCTION public.release_bundle_console() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();
BEGIN
 IF u IS NULL OR NOT release_scope(u) THEN RAISE EXCEPTION 'RELEASE_SCOPE_REQUIRED'; END IF; PERFORM care_require_strong();
 RETURN jsonb_build_object('sources',(SELECT jsonb_agg(release_bundle_source(c.register) ORDER BY c.register) FROM release_bundle_catalog() c),'snapshots',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'register',e.register,'version',e.version,'source_fingerprint',e.source_fingerprint,'source_version',e.source_version,'source_count',e.source_count,'observed_status',e.observed_status,'blocker_reason',e.blocker_reason,'mine',e.recorder=u,'created_at',e.created_at,'correlation_id',e.correlation_id,'reviews',coalesce((SELECT jsonb_agg(jsonb_build_object('outcome',r.outcome,'independent',r.reviewer<>e.recorder,'reviewer_role',r.reviewer_role,'mine',r.reviewer=u,'created_at',r.created_at,'correlation_id',r.correlation_id) ORDER BY r.created_at) FROM release_artifact_review r WHERE r.snapshot_id=e.id),'[]')) ORDER BY e.register,e.version) FROM release_artifact_snapshot e),'[]'));
END $$;
REVOKE ALL ON FUNCTION public.release_bundle_capture(text,int),public.release_bundle_confirm(uuid,text),public.release_bundle_console() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.release_bundle_capture(text,int),public.release_bundle_confirm(uuid,text),public.release_bundle_console() TO authenticated;